// @FIGURE_CODE_BEGIN
var _cont = document.getElementById('container');
var draw = SVG().addTo(_cont).size('100%', '100%');
var VW = 620, VH = 700;
draw.viewbox(0, 0, VW, VH);
draw.attr('preserveAspectRatio', 'xMidYMid meet');

var CX = 310, CY = 385, RAX = 288, SC = 79;
var AEL = 3.0, BEL = 1.5;            // semi-major / semi-minor in world units
var NAVY = '#1F3864', ORNG = '#E8622C', INK = '#111111';

var theta = 40, rotFrame = false, ptT = null;

var gAxes = draw.group();
var gConic = draw.group();
var gRot = draw.group();
var gArc = draw.group();
var gPt = draw.group();
var gTop = draw.group();

function mapX(u) { return CX + u * SC; }
function mapY(v) { return CY - v * SC; }

function ellipsePoint(t, th) {
  var xp = AEL * Math.cos(t), yp = BEL * Math.sin(t);
  return {
    xp: xp, yp: yp,
    u: xp * Math.cos(th) - yp * Math.sin(th),
    v: xp * Math.sin(th) + yp * Math.cos(th)
  };
}

function arrowHead(g, x, y, dx, dy, color, len, wid) {
  var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
  var px = -dy, py = dx;
  var bx = x - dx * len, by = y - dy * len;
  g.polygon([x + ',' + y,
  (bx + px * wid) + ',' + (by + py * wid),
  (bx - px * wid) + ',' + (by - py * wid)].join(' ')).fill(color).stroke('none');
}

function axisArrow(g, dx, dy, len, color, w, hl, hw) {
  var x1 = CX - dx * len, y1 = CY - dy * len, x2 = CX + dx * len, y2 = CY + dy * len;
  var ln = g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' });
  arrowHead(g, x2, y2, dx, dy, color, hl, hw);
  arrowHead(g, x1, y1, -dx, -dy, color, hl, hw);
  return ln;
}

function label(g, str, x, y, o) {
  o = o || {};
  var t = g.plain(str);
  t.font({
    family: o.family || 'Georgia, "Times New Roman", serif',
    size: o.size || 14,
    style: o.style || 'normal',
    weight: o.weight || 'normal',
    anchor: o.anchor || 'middle'
  });
  t.fill(o.fill || INK);
  t.attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.haloW || 3.5, 'stroke-linejoin': 'round' });
  return t;
}

function richLine(g, parts, x, y, size) {
  var cur = x;
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    var t = g.plain(p.s);
    t.font({
      family: 'Georgia, "Times New Roman", serif',
      size: p.size || size,
      style: p.plainStyle ? 'normal' : 'italic',
      weight: p.bold ? 'bold' : 'normal',
      anchor: 'start'
    });
    t.fill(p.fill || INK);
    t.attr({ x: cur, y: y, 'dominant-baseline': 'middle' });
    cur += t.bbox().width;
  }
  return cur;
}

function fmt3(v) { if (Math.abs(v) < 0.0005) v = 0; return v.toFixed(3); }
function fmtN(v) { return (Math.round(v * 100) / 100).toString(); }

function coefs(th) {
  var a2 = AEL * AEL, b2 = BEL * BEL;
  var c = Math.cos(th), s = Math.sin(th);
  return {
    A: c * c / a2 + s * s / b2,
    B: 2 * s * c * (1 / a2 - 1 / b2),
    C: s * s / a2 + c * c / b2,
    a2: a2, b2: b2
  };
}

function clientToWorld(e) {
  var pt = draw.node.createSVGPoint();
  pt.x = e.clientX; pt.y = e.clientY;
  var p = pt.matrixTransform(draw.node.getScreenCTM().inverse());
  return { u: (p.x - CX) / SC, v: (CY - p.y) / SC };
}

function onEllipseClick(e) {
  var w = clientToWorld(e), th = theta * Math.PI / 180, best = 0, bd = 1e18;
  for (var i = 0; i < 720; i++) {
    var t = i / 720 * 2 * Math.PI, P = ellipsePoint(t, th);
    var d = (P.u - w.u) * (P.u - w.u) + (P.v - w.v) * (P.v - w.v);
    if (d < bd) { bd = d; best = t; }
  }
  ptT = best;
  redraw();
  var P = ellipsePoint(ptT, th);
  showPopup('One point, two coordinate pairs',
    'In the fixed frame this point is (' + P.u.toFixed(2) + ', ' + P.v.toFixed(2) +
    '); in the rotated frame the very same point is (' + P.xp.toFixed(2) + ', ' + P.yp.toFixed(2) + '). ' +
    'They are linked by x′ = x cos θ + y sin θ and y′ = −x sin θ + y cos θ. The point never moved — only the ruler did.');
}

function showKeyInsight() {
  showPopup('Key insight',
    'The xy term in a conic\'s equation is not a property of the conic — it is a property of the coordinate frame. ' +
    'Rotate the frame by the tilt angle θ and the cross term disappears, while the curve itself never moves.');
}

function redraw() {
  var th = theta * Math.PI / 180;
  var c = Math.cos(th), s = Math.sin(th);
  gAxes.clear(); gConic.clear(); gRot.clear(); gArc.clear(); gPt.clear(); gTop.clear();

  /* ---------- fixed black frame ---------- */
  var hx = axisArrow(gAxes, 1, 0, RAX, INK, 1.7, 13, 5);
  var hy = axisArrow(gAxes, 0, -1, RAX, INK, 1.7, 13, 5);
  [hx, hy].forEach(function (ln) {
    ln.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Fixed frame: x and y never move', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The fixed frame',
          'The black x and y axes stay put no matter how the conic is tilted. Measured in this frame, a tilted ellipse needs the general form A x² + B xy + C y² = 1, and the B xy term is exactly what records the tilt.');
      });
  });
  label(gAxes, 'x', CX + RAX - 16, CY + 32, { size: 21, style: 'italic', weight: 'bold', halo: true });
  label(gAxes, 'y', CX - 20, CY - RAX + 12, { size: 21, style: 'italic', weight: 'bold', halo: true });

  /* ---------- the conic ---------- */
  var pts = [];
  for (var i = 0; i <= 260; i++) {
    var t = i / 260 * 2 * Math.PI, P = ellipsePoint(t, th);
    pts.push(mapX(P.u) + ',' + mapY(P.v));
  }
  var ps = pts.join(' ');
  gConic.polyline(ps).fill('none').stroke({ color: NAVY, width: 3.4, linejoin: 'round' });
  var hit = gConic.polyline(ps).fill('none')
    .stroke({ color: NAVY, width: 22, opacity: 0 })
    .attr('pointer-events', 'stroke').css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip('Click to read this point in both frames', e); })
    .on('mouseleave', hideTooltip)
    .on('click', onEllipseClick);

  /* ---------- rotated orange frame ---------- */
  var dxp = c, dyp = -s;              // x' direction (screen)
  var dxq = -s, dyq = -c;             // y' direction (screen)
  var ax1 = axisArrow(gRot, dxp, dyp, RAX, ORNG, 3, 17, 7);
  var ax2 = axisArrow(gRot, dxq, dyq, RAX, ORNG, 3, 17, 7);
  [ax1, ax2].forEach(function (ln) {
    ln.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Rotated frame: x′, y′ turn with the conic', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The rotated frame',
          'The orange axes are the conic\'s own axes, turned by θ from x and y. Measured against them the ellipse is in standard position, so its equation contains only x′² and y′² — no cross term at all.');
      });
  });
  // labels on the inner (toward-the-y-axis) side of each arrow
  var Lr = RAX - 16, Loff = 30;
  var Px = -s, Py = -c;               // perpendicular (screen) to x'
  label(gRot, "x′", CX + Lr * dxp + Loff * Px, CY + Lr * dyp + Loff * Py,
    { size: 20, style: 'italic', weight: 'bold', fill: ORNG, halo: true });
  var Qx = -Math.sin(th + Math.PI / 2), Qy = -Math.cos(th + Math.PI / 2);
  label(gRot, "y′", CX + Lr * dxq - Loff * Qx, CY + Lr * dyq - Loff * Qy,
    { size: 20, style: 'italic', weight: 'bold', fill: ORNG, halo: true });

  /* ---------- theta arc ---------- */
  if (theta > 2.5) {
    var r = 60;
    var x0 = CX + r, y0 = CY;
    var x1 = CX + r * c, y1 = CY - r * s;
    gArc.path('M' + x0 + ',' + y0 + ' A' + r + ',' + r + ' 0 0 0 ' + x1 + ',' + y1)
      .fill('none').stroke({ color: INK, width: 1.5 });
    arrowHead(gArc, x1, y1, -s, -c, INK, 9, 4);
    var la = th * 0.52, lr = r + 22;
    var tl = label(gArc, 'θ', CX + lr * Math.cos(la), CY - lr * Math.sin(la),
      { size: 19, style: 'italic', halo: true });
    tl.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('θ — tilt of the conic\'s axes', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The angle θ',
          'θ measures how far the conic\'s own axes are turned away from x and y. It is the single number needed to rotate the frame: substituting x = x′cosθ − y′sinθ, y = x′sinθ + y′cosθ removes the cross term.');
      });
  }

  /* ---------- probe point ---------- */
  if (ptT !== null) {
    var P = ellipsePoint(ptT, th);
    var px = mapX(P.u), py = mapY(P.v);

    // black projections
    var dsh = { dasharray: '5,4', width: 1.3 };
    gPt.line(px, py, mapX(P.u), mapY(0)).stroke({ color: '#222', width: dsh.width, dasharray: dsh.dasharray });
    gPt.line(px, py, mapX(0), mapY(P.v)).stroke({ color: '#222', width: dsh.width, dasharray: dsh.dasharray });
    gPt.line(mapX(P.u), CY - 6, mapX(P.u), CY + 6).stroke({ color: '#222', width: 1.8 });
    gPt.line(CX - 6, mapY(P.v), CX + 6, mapY(P.v)).stroke({ color: '#222', width: 1.8 });

    // orange projections
    var f1u = P.xp * c, f1v = P.xp * s;          // foot on x'
    var f2u = -P.yp * s, f2v = P.yp * c;         // foot on y'
    gPt.line(px, py, mapX(f1u), mapY(f1v)).stroke({ color: ORNG, width: dsh.width, dasharray: dsh.dasharray });
    gPt.line(px, py, mapX(f2u), mapY(f2v)).stroke({ color: ORNG, width: dsh.width, dasharray: dsh.dasharray });
    var t1x = -s, t1y = -c;
    gPt.line(mapX(f1u) - 6 * t1x, mapY(f1v) - 6 * t1y, mapX(f1u) + 6 * t1x, mapY(f1v) + 6 * t1y)
      .stroke({ color: ORNG, width: 2 });
    var t2x = -c, t2y = s;
    gPt.line(mapX(f2u) - 6 * t2x, mapY(f2v) - 6 * t2y, mapX(f2u) + 6 * t2x, mapY(f2v) + 6 * t2y)
      .stroke({ color: ORNG, width: 2 });

    gPt.circle(11).center(px, py).fill(NAVY).stroke({ color: '#fff', width: 1.4 })
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Same point, two coordinate pairs', e); })
      .on('mouseleave', hideTooltip);

    // readouts, pushed outward from the centre into open space
    var nx = px - CX, ny = py - CY, nl = Math.hypot(nx, ny) || 1;
    nx /= nl; ny /= nl;
    var lx = px + nx * 40, ly = py + ny * 40;
    lx = Math.max(78, Math.min(VW - 78, lx));
    ly = Math.max(96, Math.min(VH - 26, ly));
    label(gPt, '(' + P.u.toFixed(2) + ', ' + P.v.toFixed(2) + ')', lx, ly - 12,
      { size: 14, style: 'italic', fill: '#111', halo: true, haloW: 4 });
    label(gPt, '(' + P.xp.toFixed(2) + ', ' + P.yp.toFixed(2) + ')', lx, ly + 11,
      { size: 14, style: 'italic', fill: ORNG, halo: true, haloW: 4 });
  }

  /* ---------- top strip: equation panel + legend ---------- */
  var k = coefs(th);
  label(gTop, rotFrame ? 'Equation in the rotated (x′, y′) frame'
    : 'Equation in the original (x, y) frame',
    18, 16, { family: 'sans-serif', size: 11.5, fill: '#666', anchor: 'start' });

  var parts;
  if (!rotFrame) {
    parts = [
      { s: fmt3(k.A) + ' x² ' },
      { s: (k.B < 0 ? '− ' : '+ ') + fmt3(Math.abs(k.B)) + ' xy ', fill: ORNG, bold: true },
      { s: '+ ' + fmt3(k.C) + ' y² = 1' }
    ];
  } else {
    parts = [
      { s: 'x′²/' + fmtN(k.a2), fill: ORNG, bold: true },
      { s: '  +  ' },
      { s: 'y′²/' + fmtN(k.b2), fill: ORNG, bold: true },
      { s: '  = 1' },
      { s: '    (no x′y′ term)', fill: '#777', size: 12.5, plainStyle: true }
    ];
  }
  var endX = richLine(gTop, parts, 18, 44, 17);

  var panelHit = gTop.rect(Math.max(120, endX - 8), 46).move(12, 6)
    .fill('#fff').opacity(0).css('cursor', 'pointer');
  panelHit.on('mousemove', function (e) {
    showTooltip(rotFrame ? 'Aligned frame → only squared terms'
      : 'The xy term is the signature of the tilt', e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Two equations, one curve',
        'In the fixed frame the tilted ellipse reads A x² + B xy + C y² = 1 with B = sin2θ(1/a² − 1/b²). In the rotated frame the identical curve reads x′²/a² + y′²/b² = 1. Nothing about the ellipse changed — only the frame used to describe it.');
    });

  gTop.line(432, 20, 458, 20).stroke({ color: INK, width: 1.7 });
  label(gTop, 'fixed frame:  x, y', 464, 20,
    { family: 'sans-serif', size: 11.5, anchor: 'start', fill: '#333' });
  gTop.line(432, 44, 458, 44).stroke({ color: ORNG, width: 3 });
  label(gTop, 'rotated frame:  x′, y′', 464, 44,
    { family: 'sans-serif', size: 11.5, anchor: 'start', fill: ORNG });
}

/* ---------------- interactions ---------------- */
function update_thetaSlider(v) { theta = v; redraw(); }
function toggle_frameToggle(on) { rotFrame = !!on; redraw(); }
function trigger_pointProbe() {
  ptT = (ptT === null) ? 0.85 : null;
  redraw();
  if (ptT !== null) {
    var P = ellipsePoint(ptT, theta * Math.PI / 180);
    showPopup('One point, two coordinate pairs',
      'Black dashed drop-lines give (' + P.u.toFixed(2) + ', ' + P.v.toFixed(2) +
      ') in the fixed frame; orange drop-lines give (' + P.xp.toFixed(2) + ', ' + P.yp.toFixed(2) +
      ') in the rotated frame. Drag θ or click elsewhere on the ellipse to compare.');
  }
}

/* ---------------- demo steps ---------------- */
var STEPS = [
  {
    title: 'Aligned conic: no tilt', thetaS: 0, rot: false, point: null,
    narration: 'With θ = 0 the orange frame sits exactly on top of the black frame and the ellipse\'s major axis lies along x. The equation has no xy term.'
  },
  {
    title: 'Turn the conic away from the axes', thetaS: 40, rot: false, point: null,
    narration: 'Drag θ upward: the ellipse and the orange axes rotate together while x and y stay fixed. As soon as θ ≠ 0 an xy term appears in the (x, y) equation and grows with the tilt.'
  },
  {
    title: 'Read the same conic in the rotated frame', thetaS: 40, rot: true, point: null,
    narration: 'Switch the equation panel to the primed frame. The identical curve is now written as x′²/a² + y′²/b² = 1 — the cross term is gone because the axes match the ellipse.'
  },
  {
    title: 'One point, two coordinate pairs', thetaS: 40, rot: true, point: 0.85,
    narration: 'Click any point on the ellipse. Black dashed projections give (x, y); orange dashed projections give (x′, y′). The point is unchanged — only the measuring frame differs.'
  },
  {
    title: 'Extreme tilt', thetaS: 88, rot: false, point: null,
    narration: 'Push θ toward 90°: the ellipse\'s long axis swings onto the y-axis. The xy term shrinks back to zero at exactly 90°, showing the term measures misalignment, not shape.'
  }
];
var curStep = 1;

function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep];
  theta = s.thetaS; rotFrame = s.rot; ptT = s.point;
  var sl = document.getElementById('thetaSliderInput');
  if (sl) { sl.value = s.thetaS; document.getElementById('thetaSliderVal').value = s.thetaS; }
  var cb = document.getElementById('frameToggleInput');
  if (cb) cb.checked = s.rot;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + STEPS.length;
  redraw();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(1);
window.__markRendered();
